1	// The structural comparison behind src/oracle.ts: both sides' prop types reduced to one shape, and one verdict per
2	// pair. Pure: nothing here talks to the checker.
3	
4	/** The primitive a literal is a value of: `"0"` and `0` spell the same `value` and are two types. */
5	export type LiteralKind = 'string' | 'number' | 'bigint' | 'boolean'
6	
7	/** A type reduced to what both sides can state: kind, literal value, members, fields, parameters. `alias` is the
8	 * checker's name for it (an alias, or the interface that declares it), which Caliper may print instead. */
9	export type Norm = (
10	  | { k: 'prim'; name: string }
11	  | { k: 'lit'; value: string; of: LiteralKind }
12	  | { k: 'union'; members: Norm[] }
13	  | { k: 'intersection'; members: Norm[] }
14	  | { k: 'array'; element: Norm }
15	  | { k: 'tuple'; elements: Norm[] }
16	  | { k: 'function'; params: { optional: boolean; rest: boolean; type: Norm }[]; returns: Norm }
17	  | { k: 'object'; fields: string[]; index: boolean; indexValue?: Norm }
18	  | { k: 'name'; name: string }
19	  | { k: 'param'; name: string; fallback?: Norm; constraint?: Norm }
20	  | { k: 'opaque' }
21	  | { k: 'error' }
22	) & { alias?: string }
23	
24	export type Verdict = 'identical' | 'spelled' | 'less precise' | 'wrong' | 'checker any/error'
25	
26	export const MAX_DEPTH = 3
27	export const VERDICTS: Verdict[] = ['identical', 'spelled', 'less precise', 'wrong', 'checker any/error']
28	const RANK: Verdict[] = ['identical', 'spelled', 'less precise', 'wrong']
29	
30	/** A type name without `React.` or a namespace qualifier. */
31	export const bareName = (name: string) => name.replace(/^.*\./, '')
32	export const prim = (name: string): Norm => ({ k: 'prim', name })
33	export const lit = (value: string, of: LiteralKind): Norm => ({ k: 'lit', value, of })
34	
35	/** `{}`: an object with no property and no index signature. The one place that decides it, for every reader of a
36	 * `Norm`: an index-only object (`{ [key: string]: V }`) has no fields either, and is not empty. */
37	export const isBareObject = (m: Norm) => m.k === 'object' && m.fields.length === 0 && !m.index
38	
39	const TERMINALS: Record<string, string> = {
40	  reactNode: 'ReactNode',
41	  cssProperties: 'CSSProperties',
42	  elementType: 'ElementType',
43	  htmlAttributes: 'HTMLAttributes',
44	  ref: 'Ref',
45	  sxProps: 'SxProps',
46	}
47	const PRIMITIVES = new Set(['string', 'number', 'boolean', 'null', 'undefined', 'any', 'unknown', 'never', 'void'])
48	const LITERAL_KINDS: Record<string, LiteralKind> = {
49	  stringLiteral: 'string',
50	  numberLiteral: 'number',
51	  boolLiteral: 'boolean',
52	}
53	const LITERALS = new Set(Object.keys(LITERAL_KINDS))
54	
55	const isIndexField = (field: any) => field.indexKey !== undefined
56	
57	/** Caliper's canonical `PropType` JSON, normalized. */
58	export function caliperNorm(t: any, depth = 0): Norm {
59	  if (!t || depth > MAX_DEPTH) return { k: 'opaque' }
60	  if (PRIMITIVES.has(t.kind)) return prim(t.kind)
61	  if (LITERALS.has(t.kind)) return lit(String(t.value), LITERAL_KINDS[t.kind])
62	  const inner = (m: any) => caliperNorm(m, depth + 1)
63	  switch (t.kind) {
64	    case 'literalUnion': {
65	      return { k: 'union', members: t.members.map((m: string) => lit(m, 'string')) }
66	    }
67	    case 'union': {
68	      return { k: 'union', members: t.members.map((m: any) => inner(m)) }
69	    }
70	    case 'intersection': {
71	      const parts: Norm[] = t.members.map((m: any) => inner(m))
72	      const meaningful = parts.filter((m) => !isBareObject(m))
73	      return meaningful.length === 1 ? meaningful[0] : { k: 'intersection', members: parts }
74	    }
75	    case 'array': {
76	      return { k: 'array', element: inner(t.element) }
77	    }
78	    case 'tuple': {
79	      return { k: 'tuple', elements: (t.elements ?? t.members ?? []).map((m: any) => inner(m)) }
80	    }
81	    case 'object': {
82	      // Caliper writes an index signature as one field whose `indexKey` is the key type: its name is the signature's
83	      // parameter name (`[id: string]: number`), not a property.
84	      const indexed: any[] = t.fields.filter(isIndexField)
85	      const named: any[] = t.fields.filter((field: any) => !isIndexField(field))
86	      const indexValues: Norm[] = indexed.map((field) => inner(field.propType))
87	      return {
88	        k: 'object',
89	        fields: named.map((field) => field.name).toSorted(),
90	        index: indexed.length > 0,
91	        ...(indexed.length > 0 && {
92	          indexValue: indexValues.length === 1 ? indexValues[0] : { k: 'union', members: indexValues },
93	        }),
94	      }
95	    }
96	    // A `readonly` array or tuple is the array or tuple, as the checker reads it.
97	    case 'readonly': {
98	      return caliperNorm(t.element, depth)
99	    }
100	    case 'function': {
101	      const params = (t.params ?? []).map((p: any) => ({
102	        optional: p.optional === true,
103	        rest: p.rest === true,
104	        type: inner(p.type),
105	      }))
106	      return { k: 'function', params, returns: inner(t.returnType) }
107	    }
108	    case 'named': {
109	      return { k: 'name', name: bareName(t.name) }
110	    }
111	    default: {
112	      return TERMINALS[t.kind] ? { k: 'name', name: TERMINALS[t.kind] } : { k: 'opaque' }
113	    }
114	  }
115	}
116	
117	const worst = (vs: Verdict[]): Verdict => vs.reduce((a, b) => (RANK.indexOf(b) > RANK.indexOf(a) ? b : a), 'identical')
118	const best = (vs: Verdict[]): Verdict => vs.reduce((a, b) => (RANK.indexOf(b) < RANK.indexOf(a) ? b : a), 'wrong')
119	const isBool = (n: Norm, value: string) => n.k === 'lit' && n.of === 'boolean' && n.value === value
120	const isUndefined = (m: Norm) => m.k === 'prim' && m.name === 'undefined'
121	const WIDENING = new Set(['string', 'number', 'boolean'])
122	
123	/** An empty object type, or `Record<…>` (its arguments are not kept): what `string & {}` intersects with. */
124	const isEmptyObject = (m: Norm) => isBareObject(m) || (m.k === 'name' && m.name === 'Record')
125	
126	/** Whether `m` is the primitive `name`, or `name & {}`, or a union with either. */
127	function absorbs(m: Norm, name: string): boolean {
128	  if (m.k === 'prim') return m.name === name
129	  if (m.k === 'union') return m.members.some((member) => absorbs(member, name))
130	  return m.k === 'intersection' && m.members.some(isEmptyObject) && m.members.some((member) => absorbs(member, name))
131	}
132	
133	/** A name or opaque type that Caliper (or the checker) did not expand: what it holds is unknown, so no member beside it
134	 * can prove the other side wrong. */
135	const isUnexpanded = (m: Norm) => m.k === 'name' || m.k === 'opaque'
136	
137	/** Union members without `undefined` (an optional prop's, which both sides treat as optional), flattened, with
138	 * `true | false` as `boolean`. */
139	function members(n: Norm, coverLiterals = false): Norm[] {
140	  const flat: Norm[] = []
141	  const push = (m: Norm) => {
142	    if (m.k === 'union') m.members.forEach(push)
143	    // An optional generic prop reads `T | (undefined & T)`.
144	    else if (!isUndefined(m) && !(m.k === 'intersection' && m.members.some(isUndefined))) flat.push(m)
145	  }
146	  push(n)
147	  // `'default' | 'large' | string` is `string` to the checker: a literal that a primitive of its kind in the same
148	  // union already covers adds nothing, so a union written with it holds the same values as one without. The checker's
149	  // `"blue" | … | (string & {})` keeps its literals for the reader, so `compare` scores it spelled, not identical. A
150	  // literal is covered by the primitive of its own kind only: `"0"` is not covered by `number`, `true` not by `string`.
151	  // `string & {}` and `string & Record<never, never>` (the `LiteralUnion` spellings) are `string` for this purpose.
152	  const has = (name: string) => flat.some((m) => absorbs(m, name))
153	  const covered = (m: Norm) => coverLiterals && m.k === 'lit' && has(m.of)
154	  const kept = flat.filter((m) => !covered(m))
155	  if (kept.some((m) => isBool(m, 'true')) && kept.some((m) => isBool(m, 'false'))) {
156	    return [...kept.filter((m) => !isBool(m, 'true') && !isBool(m, 'false')), prim('boolean')]
157	  }
158	  return kept
159	}
160	
161	/** Two unions: each checker member covered by one of Caliper's (a missing member makes Caliper's type too narrow),
162	 * and each of Caliper's matched by one of the checker's (an extra member makes it too wide, unless it widens
163	 * literals). */
164	function compareUnions(cm: Norm[], km: Norm[], depth: number): Verdict {
165	  const kCovered = km.map((m) => best(cm.map((cMember) => compare(cMember, m, depth + 1))))
166	  const cMatched = cm.map((m) => {
167	    const verdict = best(km.map((kMember) => compare(m, kMember, depth + 1)))
168	    const widens =
169	      m.k === 'prim' &&
170	      WIDENING.has(m.name) &&
171	      km.some((kMember) => kMember.k === 'lit' || (kMember.k === 'prim' && kMember.name === m.name))
172	    return verdict === 'wrong' && widens ? 'less precise' : verdict
173	  })
174	  const verdict = worst([...kCovered, ...cMatched])
175	  // A union with a name or opaque member (`MantineColor | 'initials'`, a template literal) may hold the other side's
176	  // values in that member, so a member it cannot match is not proof of a different type.
177	  return verdict === 'wrong' && [...cm, ...km].some((m) => isUnexpanded(m)) ? 'less precise' : verdict
178	}
179	
180	function compareFunctions(c: Norm & { k: 'function' }, k: Norm & { k: 'function' }, depth: number): Verdict {
181	  const verdicts: Verdict[] = [compare(c.returns, k.returns, depth + 1)]
182	  for (const [i, kp] of k.params.entries()) {
183	    const cp = c.params[i]
184	    if (cp === undefined) {
185	      verdicts.push(kp.optional || kp.rest ? 'less precise' : 'wrong')
186	    } else {
187	      verdicts.push(compare(cp.type, kp.type, depth + 1))
188	      // A marker the checker has and this side lost.
189	      if ((kp.optional && !cp.optional) || (kp.rest && !cp.rest)) verdicts.push('less precise')
190	    }
191	  }
192	  if (c.params.length > k.params.length) verdicts.push('wrong')
193	  return worst(verdicts)
194	}
195	
196	/** One non-union type against another. */
197	function compareOne(c: Norm, k: Norm, depth: number): Verdict {
198	  switch (k.k) {
199	    case 'prim': {
200	      return c.k === 'prim' && c.name === k.name ? 'identical' : 'wrong'
201	    }
202	    case 'lit': {
203	      if (c.k === 'lit') return c.value === k.value && c.of === k.of ? 'identical' : 'wrong'
204	      return c.k === 'prim' && WIDENING.has(c.name) ? 'less precise' : 'wrong'
205	    }
206	    case 'array': {
207	      return c.k === 'array' ? compare(c.element, k.element, depth + 1) : 'wrong'
208	    }
209	    case 'tuple': {
210	      if (c.k !== 'tuple') return c.k === 'array' ? 'less precise' : 'wrong'
211	      if (c.elements.length !== k.elements.length) return 'wrong'
212	      return worst(c.elements.map((e, i) => compare(e, k.elements[i], depth + 1)))
213	    }
214	    case 'function': {
215	      return c.k === 'function' ? compareFunctions(c, k, depth) : 'wrong'
216	    }
217	    case 'object': {
218	      if (c.k !== 'object') return c.k === 'prim' && c.name === 'object' ? 'less precise' : 'wrong'
219	      const own = new Set(c.fields)
220	      if (c.fields.some((f) => !k.fields.includes(f))) return 'wrong'
221	      // An index signature Caliper has and the checker does not describes a different type.
222	      if (c.index && !k.index) return 'wrong'
223	      const verdicts: Verdict[] = [
224	        k.fields.some((f) => !own.has(f)) || (k.index && !c.index) ? 'less precise' : 'identical',
225	      ]
226	      // Both state an index: its value type is compared, and one a side does not state is not proof of agreement.
227	      if (c.index && k.index) {
228	        verdicts.push(c.indexValue && k.indexValue ? compare(c.indexValue, k.indexValue, depth + 1) : 'less precise')
229	      }
230	      return worst(verdicts)
231	    }
232	    case 'intersection': {
233	      if (c.k !== 'intersection') return 'less precise'
234	      return c.members.length === k.members.length ? 'identical' : 'less precise'
235	    }
236	    case 'param': {
237	      // A type parameter of the component itself, which Caliper replaced with an instantiation: its default, as a bare
238	      // `AccordionProps` means `AccordionProps<false>`, or its constraint. That is one instance of the parameter,
239	      // looser or narrower than the parameter itself, and not another type; a type that is neither instance is.
240	      // `c` may be one member of a union Caliper wrote out (`string` of `string | number`), so it must fit one member of
241	      // an instance, not all of them.
242	      const instances = [k.fallback, k.constraint].filter((i): i is Norm => i !== undefined).flatMap((i) => members(i))
243	      // A parameter with neither (a generic component cast over `forwardRef`, whose props interface declares the
244	      // default) leaves the checker no instance to hold Caliper's to: any one it picked is one value of the parameter.
245	      if (instances.length === 0) return 'less precise'
246	      return instances.some((i) => compare(c, i, depth + 1) !== 'wrong') ? 'less precise' : 'wrong'
247	    }
248	    default: {
249	      return 'wrong'
250	    }
251	  }
252	}
253	
254	/** How Caliper's normalized type `c` stands against the checker's `k`. A checker union that spells literals a
255	 * primitive in it already covers (`'a' | 'b' | (string & {})`) holds the values Caliper's `string` does, spelled
256	 * another way. */
257	export function compare(c: Norm, k: Norm, depth = 0): Verdict {
258	  const verdict = compareValues(c, k, depth)
259	  return verdict === 'identical' && members(k).length !== members(k, true).length ? 'spelled' : verdict
260	}
261	
262	function compareValues(c: Norm, k: Norm, depth: number): Verdict {
263	  if (depth > MAX_DEPTH) return 'identical'
264	  // The checker has no type to compare with: an error, `any`, or a top-level `unknown` where Caliper has a type
265	  // (most often a declaration the program couldn't resolve).
266	  const uninformative =
267	    k.k === 'error' || (k.k === 'prim' && k.name === 'any') || (depth === 0 && k.k === 'prim' && k.name === 'unknown')
268	  if (uninformative && !(c.k === 'prim' && k.k === 'prim' && c.name === k.name)) {
269	    return depth === 0 ? 'checker any/error' : 'identical'
270	  }
271	  const km = members(k, true)
272	  // An optional prop of type `never` reads `undefined` in the checker, which `members` drops as the optional marker.
273	  if (km.length === 0 && c.k === 'prim' && c.name === 'never') return 'identical'
274	  if (c.k === 'name') {
275	    // An optional prop's checker type is `X | undefined`; the name is X's.
276	    const target = km.length === 1 ? km[0] : k
277	    if ((target.alias && bareName(target.alias) === c.name) || (k.alias && bareName(k.alias) === c.name)) {
278	      return 'spelled'
279	    }
280	    if (target.k === 'param' && target.name === c.name) return 'identical'
281	    // A name Caliper left unexpanded where the checker has the type itself (an unbound parameter, an alias that
282	    // resolves to another name).
283	    return 'less precise'
284	  }
285	  if (k.k === 'opaque') return 'identical'
286	  if (c.k === 'opaque') return 'less precise'
287	  if (c.k === 'prim' && (c.name === 'any' || c.name === 'unknown') && !(k.k === 'prim' && k.name === c.name)) {
288	    return 'less precise'
289	  }
290	  // An intersection Caliper left as written, which the checker reduced (`Mode & …` to a literal union).
291	  if (c.k === 'intersection' && !km.some((m) => m.k === 'intersection')) return 'less precise'
292	  const cm = members(c, true)
293	  if (cm.length !== 1 || km.length !== 1) return compareUnions(cm, km, depth)
294	  const [cOne] = cm
295	  const [kOne] = km
296	  if (cOne !== c || kOne !== k) return compare(cOne, { ...kOne, alias: kOne.alias ?? k.alias }, depth)
297	  return compareOne(c, k, depth)
298	}
