// Dump every construct-suite row's prop type and verdict for one binary: rows.ts <bin> <worktree>
import { execFileSync } from 'node:child_process'
import { readFileSync, realpathSync } from 'node:fs'
import { join } from 'node:path'
const [bin, root] = process.argv.slice(2)
const oracle = join(root, 'apps/oracle/src')
const { checkCaliperShape, flattenProps } = await import(join(oracle, 'caliper-input.ts'))
const { listFixtures, PROP, rowVerdict } = await import(join(oracle, 'construct-suite.ts'))
const suite = realpathSync(join(root, 'apps/oracle/construct-suite'))
const stdout = execFileSync(bin, ['extract', '--src', suite, '--json', '--html-attributes', 'full', '--include-unexported',
  '--load-dependencies', '--collapse-inherited-props', 'none', '--no-cache', '--quiet'], { encoding: 'utf8', maxBuffer: 1 << 28 })
const caliper = JSON.parse(stdout)
checkCaliperShape(caliper)
const byFile = new Map<string, any>()
for (const [key, c] of Object.entries<any>(caliper.components)) {
  if (c.displayName !== 'Row') continue
  const id = flattenProps(caliper, key, c)[PROP]
  byFile.set(realpathSync(c.filePath), id === undefined ? undefined : caliper.props[id])
}
for (const f of listFixtures(suite)) {
  const golden = JSON.parse(readFileSync(f.golden, 'utf8'))
  const prop = byFile.get(realpathSync(f.file))
  console.log(`${f.id}\t${rowVerdict(prop, golden)}\t${JSON.stringify(prop?.type)}\t${JSON.stringify(prop?.degradedBy ?? [])}`)
