804	    /// Record the defaults of a declaration's type parameters (`<TLength = string | 0, TTime = string>`), when any has one.
805	    pub(super) fn record_type_param_defaults<'a>(&mut self, key: &str, params: &[TSTypeParameter<'a>]) {
806	        let defaults: Vec<Option<CollectedType>> =
807	            params.iter().map(|p| p.default.as_ref().map(|d| self.ts_type_to_collected(d))).collect();
808	        if defaults.iter().any(Option::is_some) {
