923	                                .as_ref()
924	                                .map(|rt| self.ts_type_to_collected_at_depth(&rt.type_annotation, depth + 1))
925	                                .unwrap_or(CollectedType::Any);
926	                            CollectedType::Function {
927	                                type_params: type_param_names(call.type_parameters.as_deref()),
928	                                params,
929	                                param_names,
930	                                param_kinds,
931	                                return_type: Box::new(return_type),
932	                            }
933	                        }
934	                        _ => CollectedType::Raw(self.source[lit.span.start as usize..lit.span.end as usize].to_owned()),
935	                    }
936	                } else {
937	                    let fields: Vec<CollectedObjectField> = lit
938	                        .members
939	                        .iter()
940	                        .filter_map(|member| self.ts_signature_to_object_field(member, depth + 1))
941	                        .collect();
942	                    CollectedType::Object(fields)
943	                }
944	            }
945	
946	            TSType::TSFunctionType(f) => {
947	                // In OXC 0.135, FormalParameter has type_annotation as a separate field
948	                let (params, param_names, param_kinds) =
949	                    collect_params(&f.params, |t| self.ts_type_to_collected_at_depth(t, depth + 1));
950	                // return_type on TSFunctionType is Box<TSTypeAnnotation> (not Option)
951	                let return_type = self.ts_type_to_collected_at_depth(&f.return_type.type_annotation, depth + 1);
952	                CollectedType::Function {
953	                    type_params: type_param_names(f.type_parameters.as_deref()),
954	                    params,
955	                    param_names,
956	                    param_kinds,
957	                    return_type: Box::new(return_type),
958	                }
959	            }
960	
961	            TSType::TSIndexedAccessType(ia) => CollectedType::IndexedAccess {
962	                obj: Box::new(self.ts_type_to_collected_at_depth(&ia.object_type, depth + 1)),
963	                key: Box::new(self.ts_type_to_collected_at_depth(&ia.index_type, depth + 1)),
964	            },
965	
966	            TSType::TSTemplateLiteralType(tl) => {
967	                let mut parts: Vec<CollectedType> = Vec::new();
968	                for (i, quasi) in tl.quasis.iter().enumerate() {
969	                    let s = quasi.value.raw.as_str();
970	                    if !s.is_empty() {
971	                        parts.push(CollectedType::StringLiteral(s.into()));
972	                    }
973	                    if let Some(ty) = tl.types.get(i) {
974	                        parts.push(self.ts_type_to_collected_at_depth(ty, depth + 1));
975	                    }
976	                }
977	                CollectedType::TemplateLiteral(parts)
978	            }
979	
980	            TSType::TSConditionalType(c) => CollectedType::Conditional {
981	                check: Box::new(self.ts_type_to_collected_at_depth(&c.check_type, depth + 1)),
982	                extends_type: Box::new(self.ts_type_to_collected_at_depth(&c.extends_type, depth + 1)),
983	                true_type: Box::new(self.ts_type_to_collected_at_depth(&c.true_type, depth + 1)),
984	                false_type: Box::new(self.ts_type_to_collected_at_depth(&c.false_type, depth + 1)),
985	            },
986	
987	            TSType::TSMappedType(m) => {
988	                // In OXC 0.135, TSMappedType has `constraint: TSType` directly (not via
989	                // type_parameter) and `type_annotation: Option<TSType>` (not Box<TSTypeAnnotation>)
990	                let key_type = self.ts_type_to_collected_at_depth(&m.constraint, depth + 1);
991	                let value_type = m
992	                    .type_annotation
993	                    .as_ref()
994	                    .map(|ta| self.ts_type_to_collected_at_depth(ta, depth + 1))
995	                    .unwrap_or(CollectedType::Unknown);
996	                CollectedType::Mapped {
997	                    param: m.key.name.as_str().into(),
998	                    key_type: Box::new(key_type),
999	                    value_type: Box::new(value_type),
1000	                    optional: m.optional.map(|modifier| modifier != TSMappedTypeModifierOperator::Minus),
1001	                }
1002	            }
1003	
1004	            TSType::TSParenthesizedType(p) => {
1005	                // Unwrap parentheses — (Type) → Type
1006	                self.ts_type_to_collected_at_depth(&p.type_annotation, depth + 1)
1007	            }
1008	
1009	            // TSTypeOperatorType covers keyof, unique, readonly. `keyof` is kept
1010	            // structured (its operand may itself need substitution or resolution —
1011	            // see `CollectedType::KeyOf`), and so does `readonly`. `unique` is peeled to its operand,
