1	//! Central dispatch: CollectedType → PropType.
2	
3	use camino::Utf8Path;
4	
5	use crate::types::*;
6	
7	use super::ResolutionContext;
8	use super::func::{resolve_function_type, resolve_typeof};
9	use super::named::resolve_named;
10	use super::primitives::{resolve_indexed_access, resolve_intersection, resolve_union};
11	use super::template::resolve_template_literal;
12	
13	/// `ty` without the `AtFile` markers around it.
14	fn unwrap_at_file(ty: &CollectedType) -> &CollectedType {
15	    match ty {
16	        CollectedType::AtFile { inner, .. } => unwrap_at_file(inner),
17	        other => other,
18	    }
19	}
20	
21	/// Central dispatch: convert a `CollectedType` to a `PropType`.
22	/// Never re-parses strings — everything is already structured.
23	#[allow(clippy::too_many_arguments)]
24	pub fn resolve_collected_type(
25	    ct: &CollectedType,
26	    consuming_file: &Utf8Path,
27	    ctx: &ResolutionContext,
28	    state: &mut ResolveState,
29	    depth: u8,
30	) -> PropType {
31	    if super::past_max_depth(state, depth) {
32	        let diag = super::max_depth_diagnostic(&format!("type '{}'", ct.to_raw_string()), consuming_file);
33	        return OpaqueDetail::give_up(state, ct.to_raw_string(), OpaqueReason::DepthExceeded, diag);
34	    }
35	
36	    match ct {
37	        // ── Primitives ────────────────────────────────────────────────────────
38	        CollectedType::String => PropType::String,
39	        CollectedType::Number => PropType::Number,
40	        CollectedType::Boolean => PropType::Boolean,
41	        CollectedType::Null => PropType::Null,
42	        CollectedType::Undefined => PropType::Undefined,
43	        CollectedType::Any => PropType::Any,
44	        CollectedType::Never => PropType::Never,
45	        CollectedType::Unknown => PropType::Unknown,
46	        CollectedType::Void => PropType::Void,
47	        // BigInt/Symbol — no dedicated PropType; surface as Named.
48	        CollectedType::BigInt => PropType::Named { name: "bigint".into(), args: vec![] },
49	        CollectedType::Symbol => PropType::Named { name: "symbol".into(), args: vec![] },
50	
51	        // ── Literals ─────────────────────────────────────────────────────────
52	        CollectedType::StringLiteral(s) => PropType::StringLiteral(s.to_string()),
53	        CollectedType::NumberLiteral(n) => PropType::NumberLiteral(*n),
54	        CollectedType::BoolLiteral(b) => PropType::BoolLiteral(*b),
55	
56	        // ── Composites ───────────────────────────────────────────────────────
57	        CollectedType::Union(members) => resolve_union(members, consuming_file, ctx, state, depth),
58	        CollectedType::Intersection(members) => resolve_intersection(members, consuming_file, ctx, state, depth),
59	        CollectedType::Array(inner) => {
60	            PropType::Array(Box::new(resolve_collected_type(inner, consuming_file, ctx, state, depth + 1)))
61	        }
62	        CollectedType::Tuple(members) => PropType::Tuple(
63	            members.iter().map(|m| resolve_collected_type(m, consuming_file, ctx, state, depth + 1)).collect(),
64	        ),
65	        CollectedType::Readonly(inner) => {
66	            PropType::Readonly(Box::new(resolve_collected_type(inner, consuming_file, ctx, state, depth + 1)))
67	        }
68	        CollectedType::Object(fields) => PropType::Object(
69	            fields
70	                .iter()
71	                .map(|f| ObjectField {
72	                    name: f.name.clone(),
73	                    prop_type: resolve_collected_type(&f.collected_type, consuming_file, ctx, state, depth + 1),
74	                    required: f.required,
75	                    description: f.description.clone(),
76	                    readonly: f.readonly,
77	                    index_key: f
78	                        .index_key
79	                        .as_ref()
80	                        .map(|key| Box::new(resolve_collected_type(key, consuming_file, ctx, state, depth + 1))),
81	                })
82	                .collect(),
83	        ),
84	
85	        // ── Named type reference ──────────────────────────────────────────────
86	        CollectedType::Named { name, args } => resolve_named(name, args, consuming_file, ctx, state, depth),
87	
88	        // ── typeof X ─────────────────────────────────────────────────────────
89	        CollectedType::TypeOf(name) => resolve_typeof(name, consuming_file, ctx, &mut state.diagnostics),
90	
91	        // ── keyof X — only meaningful as Omit's key argument (handled structurally
92	        // there, see resolver/alias.rs); standalone usage needs a general
93	        // type-to-key-names resolver we don't have, so degrade gracefully.
94	        CollectedType::KeyOf(target) => {
95	            // `keyof typeof Icons` over a `const` object literal: its keys. Another operand would need the keys of an
96	            // interface with its index signatures and every parent, which a partly loaded dependency can't give.
97	            if let CollectedType::TypeOf(_) = unwrap_at_file(target)
98	                && let Some(keys) = super::evaluate::keys_of(target, consuming_file, ctx, 0)
99	            {
100	                return super::primitives::union_of(keys.into_iter().map(|key| PropType::StringLiteral(key.name)));
101	            }
102	            let diag = opaque_diagnostic("a standalone 'keyof'", ct, consuming_file);
103	            OpaqueDetail::give_up(state, ct.to_raw_string(), OpaqueReason::MappedType, diag)
104	        }
105	
106	        // ── Generic-alias substitution marker — switch file context to where
107	        // `inner` was actually written (see the `CollectedType::AtFile` doc
108	        // comment) and continue resolving from there.
109	        CollectedType::AtFile { file, inner } => resolve_collected_type(inner, file, ctx, state, depth),
110	
111	        // ── Indexed access ───────────────────────────────────────────────────
112	        CollectedType::IndexedAccess { obj, key } => {
113	            resolve_indexed_access(obj, key, consuming_file, ctx, state, depth)
114	        }
115	
116	        // ── Template literal ─────────────────────────────────────────────────
117	        CollectedType::TemplateLiteral(parts) => resolve_template_literal(parts, consuming_file, ctx, state, depth),
118	
119	        // ── Function type ─────────────────────────────────────────────────────
120	        CollectedType::Function { type_params, params, param_names, param_kinds, return_type } => {
121	            resolve_function_type(type_params, params, param_names, param_kinds, return_type)
122	        }
123	
124	        // ── Opaque (needs type checker) ───────────────────────────────────────
125	        CollectedType::Conditional { .. } => {
126	            // The branch a decidable conditional takes (`resolver/evaluate.rs`).
127	            if let Some((branch, branch_file)) = super::evaluate::reduce(ct, consuming_file, ctx, 0) {
128	                return resolve_collected_type(&branch, &branch_file, ctx, state, depth + 1);
129	            }
130	            let diag = opaque_diagnostic("a conditional type", ct, consuming_file);
131	            OpaqueDetail::give_up(state, ct.to_raw_string(), OpaqueReason::ConditionalType, diag)
132	        }
133	        CollectedType::Mapped { .. } => {
134	            let diag = opaque_diagnostic("a mapped type", ct, consuming_file);
135	            OpaqueDetail::give_up(state, ct.to_raw_string(), OpaqueReason::MappedType, diag)
136	        }
137	
138	        // ── Raw fallback ─────────────────────────────────────────────────────
139	        CollectedType::Raw(s) => {
140	            let trimmed = s.trim();
141	            // `typeof X` — ExtendsRef.type_args serialized form; resolve as Named.
142	            if let Some(name) = trimmed.strip_prefix("typeof ") {
143	                return PropType::Named { name: name.trim().into(), args: vec![] };
144	            }
145	            // Double-quoted string literal: `"button"` → StringLiteral.
146	            if trimmed.starts_with('"') && trimmed.ends_with('"') && trimmed.len() >= 2 {
147	                return PropType::StringLiteral(trimmed[1..trimmed.len() - 1].to_owned());
148	            }
149	            // Single-quoted string literal: `'button'` → StringLiteral.
150	            if trimmed.starts_with('\'') && trimmed.ends_with('\'') && trimmed.len() >= 2 {
151	                return PropType::StringLiteral(trimmed[1..trimmed.len() - 1].to_owned());
152	            }
153	            // TypeScript primitive keywords — tuple elements come through Raw because
154	            // TSTupleElement falls through to source-text extraction for non-optional,
155	            // non-rest elements. Recognise keywords here so they emit the proper PropType.
156	            match trimmed {
157	                "string" => return PropType::String,
158	                "number" => return PropType::Number,
159	                "boolean" => return PropType::Boolean,
160	                "null" => return PropType::Null,
161	                "undefined" => return PropType::Undefined,
162	                "never" => return PropType::Never,
163	                "void" => return PropType::Void,
164	                "any" => return PropType::Any,
165	                "unknown" => return PropType::Unknown,
166	                _ => {}
167	            }
168	            // A plain identifier (possibly qualified) names a type; any other text is syntax the extractor did not
169	            // structure, so it degrades with a diagnostic instead of becoming a `Named` type called `[string]`.
170	            let is_identifier = trimmed.starts_with(|c: char| c.is_alphabetic() || c == '_' || c == '$')
171	                && trimmed.chars().all(|c| c.is_alphanumeric() || matches!(c, '_' | '$' | '.'));
172	            if is_identifier {
173	                PropType::Named { name: trimmed.into(), args: vec![] }
174	            } else {
175	                let diag = opaque_diagnostic("an unparsable raw type expression", ct, consuming_file);
176	                OpaqueDetail::give_up(state, s.clone(), OpaqueReason::UnsupportedExpression, diag)
177	            }
178	        }
179	    }
180	}
181	
182	/// Build the diagnostic explaining why a `CollectedType` degrades to
183	/// `PropType::Opaque` — expanding it needs the TypeScript type checker (or,
184	/// for the Raw fallback, needs the extractor to understand a syntax shape it
185	/// doesn't yet). Pure builder — the caller passes the result to
186	/// `OpaqueDetail::give_up`, which pushes it.
187	fn opaque_diagnostic(what: &str, ct: &CollectedType, file: &Utf8Path) -> Diagnostic {
188	    Diagnostic {
189	        severity: DiagnosticSeverity::Info,
190	        message: format!(
191	            "'{}' is {} and can't be statically resolved — it will appear as opaque",
192	            ct.to_raw_string(),
193	            what
194	        ),
195	        file: Some(file.to_string()),
196	        line: None,
197	        column: None,
198	        help: None,
199	        code: DiagnosticCode::OpaqueType,
200	        affects: Vec::new(),
201	    }
202	}
