fn tuple_elements_keep_their_rest_optional_and_label_markers() {
    let out = extracted();
    let cases = [
        ("rest", "[string, ...number[]]"),
        ("leadingRest", "[...string[], number]"),
        ("labeledRest", "[head: string, ...tail: number[]]"),
        ("optional", "[string, number?]"),
        ("labeledOptional", "[x: number, y?: number]"),
