    assert_eq!(rdt, &json!("`${number}px`"));
    assert_eq!(wire, &json!({ "kind": "templateLiteral", "parts": [{ "type": { "kind": "number" } }, { "text": "px" }] }));
    assert_eq!(degraded, None, "the pattern is the exact type");
