#[test]
fn a_recursive_alias_refers_back_to_itself_by_name() {
    let out = extracted();
    let (rdt, wire, degraded) = prop(&out, "json");
    assert_eq!(rdt, &json!("string | number | boolean | null | Json[] | { [key: string]: Json }"));
