    let out = extracted();
    assert_eq!(prop(&out, "getter").0, &json!("{ readonly size: number }"));
    assert_eq!(prop(&out, "inlineAccessor").0, &json!("{ value: string }"));
    assert_eq!(prop(&out, "label").0, &json!("string"));
}

