    result = {}
    for key, component in doc["components"].items():
        for set_id in component["props"]:
            for name, prop_id in doc["propSets"][set_id].items():
                result[(key, name)] = doc["props"][prop_id]
        for name, prop_id in component.get("notableInherited", {}).items():
            result[(key, "inherited:" + name)] = doc["props"][prop_id]
    return result


def kinds(value, found):
