    print(f"{fixture}: {len(changed)} props changed {sorted(why)}; +{len(diags)} -{len(gone)} diagnostics; other fields differ: {other}")
    for k in changed[:4]:
        print("   ", k)
    for d in diags[:3]:
        print("    +diag", d["code"], d["message"][:120])
    for d in gone[:3]:
        print("    -diag", d["code"], d["message"][:120])
    for fmt in ("toon", "rdt"):
        a = open(os.path.join(OUT, "main", f"{fixture}.{fmt}")).read().splitlines()
        b = open(os.path.join(OUT, "branch", f"{fixture}.{fmt}")).read().splitlines()
        for line in difflib.unified_diff(a, b, lineterm="", n=0):
            if not line.startswith(("---", "+++", "@@")):
                print(f"    {fmt}:", line[:200])

