/// (`...number[]`); or, for anything else (`...U` of a type parameter), a variadic element of `T` itself.
pub(super) fn tuple_of(
    elements: &[CollectedTupleElement],
    mut read: impl FnMut(&CollectedType) -> PropType,
) -> PropType {
